import AppKit

public enum PasteboardCapture {
    /// The markers from nspasteboard.org, older ones some apps still write, and Stowia's own marker on what it puts back.
    public static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType", "Pasteboard generator type", "net.antelle.keeweb",
        "com.agilebits.onepassword", "com.typeit4me.clipping", "com.hamzabasaran.stowia.restored"
    ]
    public static let ownMarker = NSPasteboard.PasteboardType("com.hamzabasaran.stowia.restored")
    private static let allowed: Set<NSPasteboard.PasteboardType> = [.string, .rtf, .html, .png, .tiff, .fileURL, .URL]

    public static func read(_ board: NSPasteboard, source: String, bundle: String,
                            preferences: Preferences, maxBytes: Int = 25 * 1024 * 1024) -> (Clip, ClipboardPayload)? {
        guard !preferences.excludedBundles.contains(bundle),
              let items = board.pasteboardItems, !items.isEmpty,
              !items.contains(where: { item in item.types.contains { sensitiveTypes.contains($0.rawValue) } }) else { return nil }
        var representations: [[Representation]] = []
        var bytes = 0
        for item in items {
            var collected: [Representation] = []
            for type in item.types where allowed.contains(type) {
                guard let data = item.data(forType: type) else { continue }
                bytes += data.count
                guard bytes <= maxBytes else { return nil }
                collected.append(Representation(type: type.rawValue, data: data))
            }
            guard !collected.isEmpty else { return nil }
            representations.append(collected)
        }
        let fileURLs = items.compactMap { $0.string(forType: .fileURL) }.compactMap(URL.init(string:))
        let strings = items.compactMap { $0.string(forType: .string) ?? $0.string(forType: .URL) }
        let text = strings.joined(separator: "\n")
        let isImage = items.contains { $0.types.contains(.png) || $0.types.contains(.tiff) }
        let kind: ClipKind
        let display: String
        if !fileURLs.isEmpty {
            kind = .file; display = fileURLs.map(\.path).joined(separator: "\n")
        } else if isImage { kind = .image; display = text }
        else if strings.count == 1, let url = URL(string: text.trimmingCharacters(in: .whitespacesAndNewlines)),
                ["https", "http"].contains(url.scheme?.lowercased() ?? ""), url.host != nil {
            kind = .link; display = text
        } else { kind = .text; display = text }
        guard kind != .text || !display.isEmpty else { return nil }
        let payload = ClipboardPayload(items: representations)
        return (Clip(fingerprint: payload.fingerprint, kind: kind, text: display, source: source,
                     sourceBundle: bundle, byteCount: payload.byteCount), payload)
    }
    @discardableResult
    public static func restore(_ payload: ClipboardPayload, to board: NSPasteboard, plainText: String? = nil) -> Bool {
        let items: [NSPasteboardItem]
        if let plainText {
            let item = NSPasteboardItem(); item.setString(plainText, forType: .string); items = [item]
        } else {
            items = payload.items.map { representations in
                let item = NSPasteboardItem()
                for rep in representations { item.setData(rep.data, forType: NSPasteboard.PasteboardType(rep.type)) }
                return item
            }
        }
        guard let first = items.first else { return false }
        first.setString("1", forType: ownMarker)
        board.clearContents()
        return board.writeObjects(items)
    }
}
